<?php declare(strict_types=1); namespace App\Modules\Tourism\Services; use App\Modules\Tourism\Models\TourismExperience; use RuntimeException; final class TourismExperienceService{private TourismExperience $m;public function __construct(){$this->m=new TourismExperience();}public function all(int $t,bool $d=false):array{return $this->m->all($t,$d);}public function find(int $t,int $id,bool $d=false):?array{return $this->m->find($t,$id,$d);}public function save(int $t,?int $id,array $i,int $u):int{$d=$this->v($i);$d['slug']=$this->slug($t,$this->slugify($d['title']),$id);return $this->m->create($t,$d,$u);}public function update(int $t,int $id,array $i,int $u):void{$d=$this->v($i);$d['slug']=$this->slug($t,$this->slugify($d['title']),$id);$old=$this->m->find($t,$id);if(!$old)throw new RuntimeException('Experience not found.');$this->m->update($t,$id,$d,$u);}public function delete(int $t,int $id,int $u):void{$this->m->delete($t,$id,$u);}public function restore(int $t,int $id,int $u):void{$this->m->restore($t,$id,$u);}public function providers(int $t):array{return app()->get('db')->fetchAll("SELECT id,legal_name,provider_type FROM tourism_providers WHERE tenant_id=? AND deleted_at IS NULL ORDER BY legal_name",[$t]);}public function destinations(int $t):array{return app()->get('db')->fetchAll("SELECT id,name,district FROM tourism_destinations WHERE tenant_id=? AND deleted_at IS NULL ORDER BY name",[$t]);}private function v(array $i):array{$d=['provider_id'=>($i['provider_id']??'')===''?null:(int)$i['provider_id'],'destination_id'=>($i['destination_id']??'')===''?null:(int)$i['destination_id'],'title'=>trim((string)($i['title']??'')),'description'=>trim((string)($i['description']??''))?:null,'experience_type'=>trim((string)($i['experience_type']??''))?:null,'duration_minutes'=>($i['duration_minutes']??'')===''?null:max(1,(int)$i['duration_minutes']),'price'=>$this->money($i['price']??null),'max_participants'=>($i['max_participants']??'')===''?null:max(1,(int)$i['max_participants']),'meeting_point'=>trim((string)($i['meeting_point']??''))?:null,'included'=>trim((string)($i['included']??''))?:null,'requirements'=>trim((string)($i['requirements']??''))?:null,'latitude'=>$this->coord($i['latitude']??null,-90,90),'longitude'=>$this->coord($i['longitude']??null,-180,180),'cover_image_path'=>trim((string)($i['cover_image_path']??''))?:null,'status'=>trim((string)($i['status']??'Draft'))?:'Draft','featured'=>empty($i['featured'])?0:1];if(!$d['title'])throw new RuntimeException('Experience title is required.');if(($d['latitude']===null)!==($d['longitude']===null))throw new RuntimeException('Latitude and longitude must be provided together.');return $d;}private function money($v):?string{$v=trim((string)$v);return $v===''?null:(is_numeric($v)&&$v>=0?number_format((float)$v,2,'.',''):throw new RuntimeException('Invalid price.'));}private function coord($v,$a,$b):?string{$v=trim((string)$v);return $v===''?null:(is_numeric($v)&&$v>=$a&&$v<=$b?number_format((float)$v,7,'.',''):throw new RuntimeException('Invalid coordinates.'));}private function slug($t,$b,$id=null){$b=$b?:'experience';$c=$b;$n=2;while($this->m->slugExists($t,$c,$id))$c=$b.'-'.$n++;return $c;}private function slugify($v){$v=strtolower(trim($v));$v=preg_replace('/[^a-z0-9]+/','-',$v)??'';return trim($v,'-');}}
